$(document).ready(function() {

    $(document).on("click", function(event){
        var $trigger = $(".small_dropdown2");
        if($trigger !== event.target && !$trigger.has(event.target).length){
            $(".dd_content2").hide();
        }
    });
    $(document).on("click", function(event){
        var $trigger = $(".mega-dropdown");
        if($trigger !== event.target && !$trigger.has(event.target).length){
            $(".dropdown-content").hide();
        }
    });

});

